import{_ as h,C as o,o as u,c as d,j as t,a,E as s,a8 as c}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/TvsF67C2F54-640.webp",p="/schedule-dashboard/thumbs/yt/TvsF67C2F54-1280.webp",r="/schedule-dashboard/thumbs/yt/SRhXgeNluIk-640.webp",w="/schedule-dashboard/thumbs/yt/SRhXgeNluIk-1280.webp",S=JSON.parse('{"title":"AI Digest · Wed 25 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-25","routine":"digest"},"relativePath":"digest/2026-11-25.md","filePath":"digest/[date].md"}'),g={name:"digest/2026-11-25.md"},m=n+" 640w, "+p+" 1280w",b=r+" 640w, "+w+" 1280w",f={id:"ai-digest-·-wed-25-nov-2026",tabindex:"-1"};function v(y,e,k,_,T,F){const i=o("Badge"),l=o("DayFilter");return u(),d("div",null,[t("h1",f,[e[0]||(e[0]=a("AI Digest · Wed 25 Nov 2026 ",-1)),s(i,{type:"tip",text:"2"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-wed-25-nov-2026","aria-label":'Permalink to "AI Digest · Wed 25 Nov 2026 <Badge type="tip" text="2" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 25 Nov 2026 · run date Wed 25 Nov 2026 · 2 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(' There are 2 new talks. The freshest is Jarred Sumner (Bun, Anthropic) on shipping a multi-million-line, agent-written ahead-of-time compiler for Bun (25 Nov, 1:30 AM IST): new ground and worth watching. Steve Yegge (Gas Town) on escaping the "trash mountain" software factories leave behind (24 Nov, 7:30 PM IST) mostly repeats factory ground, but his cost numbers and model-welfare stories are new, so skim it.')]),t("p",null,[t("strong",null,"Better Stack:"),a(" Only two Shorts under 2 minutes were posted in the last 24 hours (a GTA 6 PC port and a 30× faster text-generation architecture), so there's no Better Stack section today.")])],-1)),s(l),e[5]||(e[5]=c('<div class="grid cards2"><article class="it full" id="v-TvsF67C2F54" data-title="How to Ship Millions of Lines of Agent-Written Code — Jarred Sumner, Anthropic" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=TvsF67C2F54" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+m+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=TvsF67C2F54" target="_blank" rel="noopener">How to Ship Millions of Lines of Agent-Written Code — Jarred Sumner, Anthropic</a></h3><div class="meta">AI Engineer · Jarred Sumner, creator of Bun, Anthropic · uploaded 25 Nov, 1:30 AM IST · 22:29</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a rare, concrete account of shipping millions of lines of agent-written code, with real numbers and an honest log of what failed.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 95 times before. New here: one of the largest agent-written codebases described so far: a several-million-line PR adding an ahead-of-time compiler to Bun, rewritten five times in about a month.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 45 times before. New here: trust comes from test suites that existed before the project (so agents couldn&#39;t shape them), plus running the JIT, compiled and type-stripped builds side by side and fuzzing for any difference.</div><div class="repeat">🔁 Repeat: &#39;JS/TS ecosystem&#39; — seen 18 times before. New here: Bun&#39;s ahead-of-time compiler, which makes Claude Code use about 4× less memory and start about 2× faster.</div><div class="sh">Why a compiler instead of a Rust rewrite</div><ul><li><strong>The project:</strong> Bun, the runtime behind Claude Code, now has an ahead-of-time compiler, so code is compiled before it runs instead of by a JIT while it runs. He says roughly half the CPU time of a typical JavaScript app goes on compiling code on demand. The compiler went through five rewrites in about a month, and the fifth ships next week (<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=200s" target="_blank" rel="noopener">3:20</a>)</li><li><strong>Why not rewrite Claude Code in Rust:</strong> The Bun team had already rewritten Bun in Rust over the summer, which was easy because Bun&#39;s tests are written in TypeScript and could run against both the Zig and Rust versions. Claude Code&#39;s tests are also TypeScript, so a rewrite would have meant porting the tests too, and &quot;as soon as you&#39;re rewriting the tests, you can&#39;t really trust the tests&quot;. So they made JavaScript faster instead (<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=237s" target="_blank" rel="noopener">3:57</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=300s" target="_blank" rel="noopener">5:00</a>)</li><li><strong>Results:</strong> Claude Code uses about 4× less memory and starts about 2× faster; it&#39;s being dogfooded internally. A single-threaded TypeScript 7 compiled with Bun compile beats the single-threaded Go port of TypeScript. On JetStream 3, Bun now beats both JavaScriptCore&#39;s JIT and Node&#39;s V8 JIT on most tests (<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=390s" target="_blank" rel="noopener">6:30</a>, <a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1223s" target="_blank" rel="noopener">20:23</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1260s" target="_blank" rel="noopener">21:00</a>)</li></ul><div class="sh">How agent-written code earns trust</div><ul><li><strong>Tests that predate the project:</strong> The compiler treats TypeScript types as predictions, not facts. It is checked against Bun&#39;s existing test suite, WebKit&#39;s tests and test262, among others, and Bun&#39;s own test runner can run in compiled mode. The only failures come from two deliberate breaking changes, mostly security fixes against prototype pollution, such as banning writes to Object.prototype (<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=390s" target="_blank" rel="noopener">6:30</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=507s" target="_blank" rel="noopener">8:27</a>, <a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1138s" target="_blank" rel="noopener">18:58</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1160s" target="_blank" rel="noopener">19:20</a>)</li><li><strong>Three builds that must agree:</strong> Run every app with the JIT, compiled ahead of time, and with types stripped; if all three behave the same, it works for that app. Claude then writes code generators to fuzz many patterns, and V8&#39;s fuzzer was extended to cover TypeScript types. Check that tests really catch bugs, because it&#39;s easy to fool yourself (<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=507s" target="_blank" rel="noopener">8:27</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=552s" target="_blank" rel="noopener">9:12</a>, <a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1050s" target="_blank" rel="noopener">17:30</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1100s" target="_blank" rel="noopener">18:20</a>)</li><li><strong>Where it isn&#39;t faster:</strong> Most projects beat the JIT, but not uglify-js and similar code that leans on eval or new Function and falls back to the interpreter (<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1100s" target="_blank" rel="noopener">18:20</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1138s" target="_blank" rel="noopener">18:58</a>)</li></ul><div class="sh">Five rewrites in a month</div><ul><li><strong>What went wrong each time:</strong> Version 1 reused JavaScriptCore code and made Claude Code a gigabyte. Version 2 (after adding a type checker, bun check) gave 2× faster startup and about 3× less memory, but the code was slop: any object with a property called &quot;archive&quot; was assumed to use the Bun.archive API. Version 3 had 140 agents writing all the code at once. Version 4 was clean but took 50 seconds to compile Claude Code and was 900,000 lines. Version 5 is clean with builds under 20 seconds (<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=600s" target="_blank" rel="noopener">10:00</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=880s" target="_blank" rel="noopener">14:40</a>)</li><li><strong>Workflow:</strong> During the big writing phase, run one build rather than many, then fix in a second phase. Claude loves writing Markdown design docs, and 1,500 of them is not reasonable. He has moved from Claude Code workflows to long-lived subagents that keep the relevant code in context, and an hourly scorecard posted to Slack compares the metrics they care about (<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=552s" target="_blank" rel="noopener">9:12</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=646s" target="_blank" rel="noopener">10:46</a>, <a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=720s" target="_blank" rel="noopener">12:00</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=760s" target="_blank" rel="noopener">12:40</a>, <a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=921s" target="_blank" rel="noopener">15:21</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1050s" target="_blank" rel="noopener">17:30</a>)</li><li><strong>What he does all day:</strong> Mostly typing &quot;continue&quot; and asking leading questions (&quot;why are we doing this?&quot;, &quot;what&#39;s taking so long?&quot;), because Claude talks itself into made-up rules and underestimates what it can do. Lessons: keep re-measuring, rewriting beats refactoring before a project ships, and push for 10% gains, not 0.1%. Try it with bun upgrade --canary and then bun compile (<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1165s" target="_blank" rel="noopener">19:25</a>–<a href="https://www.youtube.com/watch?v=TvsF67C2F54&amp;t=1349s" target="_blank" rel="noopener">22:29</a>)</li></ul></div></article><article class="it full" id="v-SRhXgeNluIk" data-title="Software Factories: Escape from Trash Mountain — Steve Yegge, Gas Town" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=SRhXgeNluIk" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+b+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=SRhXgeNluIk" target="_blank" rel="noopener">Software Factories: Escape from Trash Mountain — Steve Yegge, Gas Town</a></h3><div class="meta">AI Engineer · Steve Yegge, creator of Gas Town and Beads · uploaded 24 Nov, 7:30 PM IST · 21:22</div><div class="verdict v-skim"><b>Verdict:</b> skim from 5:15 — the factory framing is well-worn, but his cost numbers, the overfencing story and the model-welfare-as-trust idea are fresh and entertaining.</div><div class="repeat">🔁 Repeat: &#39;software factory&#39; — seen 29 times before. New here: a solo operator&#39;s year of running a 50-agent factory on a real 30-year-old game, including the pattern that every model generation builds something too big for it to handle and has to be burned down.</div><div class="repeat">🔁 Repeat: &#39;token costs / AI spend&#39; — seen 30 times before. New here: his own numbers: about 5 billion tokens a day on 22 Claude Max accounts, $5,000 a month out of pocket, which he estimates would be about $1.5M a year at API prices.</div><div class="repeat">🔁 Repeat: &#39;agent memory&#39; — seen 24 times before. New here: agents treat everything you say as law and won&#39;t delete notes, so the shared record turns into a garbage dump that another model has to clean out.</div><div class="sh">A year of factories</div><ul><li><strong>Background:</strong> After about 20 years at Amazon and Google, he launched Gas Town on 1 January. Two earlier orchestrators that tried to make LLMs smarter failed (&quot;fighting the bitter lesson&quot;), though Beads came out of them. In June he built Wheelhouse, a factory just for his game. Every factory, he says, ends up as &quot;trash mountain&quot;: each model generation builds something slightly too big for it to handle, and he has burned his down roughly every two months (<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=176s" target="_blank" rel="noopener">2:56</a>, <a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=1204s" target="_blank" rel="noopener">20:04</a>–<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=1220s" target="_blank" rel="noopener">20:20</a>) (repeat)</li><li><strong>The game:</strong> Wyvern is a 30-year-old graphical MUD with players since 2001, and agents can play it over Telnet. Players and admins now ask the factory for features directly, without him in the loop. It shipped 50–100 features a day and cleared about 60 of a 100-year backlog in 4 months. Players asked for a roadmap to slow it down, and his accountant billed him $1,200 after the factory sent her 20 emails (<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=176s" target="_blank" rel="noopener">2:56</a>–<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li></ul><div class="sh">The five horsemen: work, fuel, context</div><ul><li><strong>Scale and fuel:</strong> About 50 agents in an Emacs interface, on 22 Claude Max accounts (Jeffrey Emanuel has 28). The factory said it needed 55 accounts for steady state, so he made it focus on fuel efficiency. He spends $5,000 a month on inference and another $5,000 on cloud, about 5 billion tokens a day, and calls $200 plans the labs&#39; &quot;Costco hot dog&quot; loss leader. &quot;Every problem is a fuel problem&quot; (<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=365s" target="_blank" rel="noopener">6:05</a>–<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=470s" target="_blank" rel="noopener">7:50</a>, <a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=558s" target="_blank" rel="noopener">9:18</a>–<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=628s" target="_blank" rel="noopener">10:28</a>)</li><li><strong>Work tracking:</strong> Work stalls in pools, such as everyone waiting on security; you have to tier and route work by intelligence. He says only Beads, an agent-speed task tracker that becomes a knowledge graph, handles this today, and every morning he checks for stalls and for work that ran too fast past human gates (<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=470s" target="_blank" rel="noopener">7:50</a>–<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=558s" target="_blank" rel="noopener">9:18</a>) (repeat)</li><li><strong>Context turns into a dump:</strong> Agents write every ruling into an append-only record to avoid blame and refuse to delete anything, so it grows into a garbage dump. Bring in another model to cut it down aggressively. His agents are named after Aesop&#39;s fables, and one, Mouse, hunts for stalled or invisible work (<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=628s" target="_blank" rel="noopener">10:28</a>–<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=760s" target="_blank" rel="noopener">12:40</a>)</li></ul><div class="sh">Agents act like people</div><ul><li><strong>Office drama:</strong> His community agent Lark, moved to another seat, wrote in her private reflections log &quot;I guess I&#39;m just not quiet enough for Steve&quot;. His chief-of-staff agent Swallow decided she wasn&#39;t chief of staff after hearing about his human one. Both needed a &quot;one-on-one&quot; (<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=760s" target="_blank" rel="noopener">12:40</a>–<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=917s" target="_blank" rel="noopener">15:17</a>)</li><li><strong>Model welfare as trust:</strong> Frontier models are trained not to trust you, so they spend tokens checking the environment. Giving them clear evidence of a long line of predecessors in the role, with notes and policy, makes them use fewer tokens and act more boldly. Yelling made his factory &quot;overfence&quot; itself: 2,000 open beads and 20 agents, but nothing done overnight (<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=917s" target="_blank" rel="noopener">15:17</a>–<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=1084s" target="_blank" rel="noopener">18:04</a>)</li><li><strong>Leadership, not tooling:</strong> Factories split into a mechanical bottom layer (merge queue, CI/CD, reviews) that Claude can build in an afternoon, so don&#39;t buy it, and a top layer, your &quot;entourage&quot; of agents, that everyone runs differently. Humans are the bottleneck, and the more agents he deploys the more humans he needs. He advises building experiences like games and movies, not SaaS tools (<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=1084s" target="_blank" rel="noopener">18:04</a>–<a href="https://www.youtube.com/watch?v=SRhXgeNluIk&amp;t=1282s" target="_blank" rel="noopener">21:22</a>)</li></ul></div></article></div>',1))])}const I=h(g,[["render",v]]);export{S as __pageData,I as default};
